#include "rpg/battle.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;
void check(bool v,const char* message){if(!v){throw std::runtime_error(message);}}
struct Fixture{
 std::vector<Definition> roster{{"F",Team::A,1000,20,100},{"P",Team::A,1000,1,90},{"B",Team::B,1000,10,200},{"B2",Team::B,1000,1,80}};
 BattleRules rules;
 Fixture(){rules.combat_model=resolution::CombatModel::FunnelV1;for(auto& d:roster){d.stats.block=0;}roster[0].vigil=VigilDefinition{"F-A1",5,4};SkillDefinition a1{"F-A1","F",0,TargetRule::Enemy,{{EffectKind::Damage}}};a1.basic=true;a1.effects[0].power_ratio=11000;EffectDefinition multi{EffectKind::Damage};multi.hit_count=3;rules.skills={a1,{"multi","B",0,TargetRule::Enemy,{multi}}};}
};
std::size_t count(const ActionResult& r,EventType type){return static_cast<std::size_t>(std::ranges::count(r.events,type,&Event::type));}
const Status* shield(const Battle& b,const char* id){const auto& statuses=b.find(id)->statuses;const auto f=std::ranges::find(statuses,EffectKind::StandardShield,&Status::kind);return f==statuses.end()?nullptr:&*f;}
int main(){try{
 Fixture f;Battle b(f.roster,f.rules,{{"F",1000},{"P",500},{"B",1000},{"B2",1000}});auto r=b.apply({"B",ActionType::Skill,"F","multi"});check(r.accepted()&&count(r,EventType::PassiveTriggered)==1,"one activation per skill");check(b.find("F")->vigil_charges==0&&b.find("B")->health==978,"consume and A1");check(shield(b,"P")&&shield(b,"P")->magnitude==10&&shield(b,"P")->remaining==3,"lowest HP percent shield");auto lastHit=std::ranges::find_if(r.events,[](const Event& e){return e.actor=="B"&&e.hit_index==3&&e.type==EventType::Attack;});auto triggered=std::ranges::find(r.events,EventType::PassiveTriggered,&Event::type);check(lastHit<triggered,"after all hits");
 f.roster[0].vigil->initial_charges=0;Battle single(f.roster,f.rules);r=single.apply({"B",ActionType::Skill,"F","multi"});check(single.find("F")->vigil_charges==1&&count(r,EventType::PassiveTriggered)==0,"multihit counts ally once; capacity stays five");
 for(auto contact:{0,1,2,3}){Fixture c;if(contact==0){c.roster[0].stats.block=10000;c.roster[0].stats.special_block_cap=true;}if(contact==1){c.roster[2].stats.miss=10000;}if(contact==2){c.roster[0].stats.invincible=true;}std::vector<InitialRuntime> states;if(contact==3){states.push_back({"F",100,{{EffectKind::Shield,3,TickPolicy::NaturalOnly,0,500}},{{"F-A1",0}}});}Battle scenario(c.roster,c.rules,{},states);r=scenario.apply({"B",ActionType::Skill,"F","multi"});check(count(r,EventType::PassiveTriggered)==((contact==0||contact==3)?1u:0u),"block/shield count; miss/invincible do not");}
 Fixture area;area.roster[0].vigil->initial_charges=0;for(int i=0;i<3;++i){Definition ally{"X"+std::to_string(i),Team::A,1000,1,70-i};ally.stats.block=0;area.roster.push_back(ally);}area.rules.skills[1].target=TargetRule::EnemyTeam;Battle aoe(area.roster,area.rules);r=aoe.apply({"B",ActionType::Skill,"F","multi"});check(count(r,EventType::PassiveTriggered)==1&&aoe.find("F")->vigil_charges==0,"five allies AoE; overflow discarded");
 for(auto border:{StatusBorder::Golden,StatusBorder::Silver,StatusBorder::Common}){Fixture c;c.roster[0].vigil->charge_border=border;c.roster[2].max_health=10;InitialRuntime reflect{"F",100,{{EffectKind::Reflect,2,TickPolicy::NaturalOnly,0,100}},{{"F-A1",0}}};Battle cancelled(c.roster,c.rules,{}, {reflect});r=cancelled.apply({"B",ActionType::Attack,"F"});check(count(r,EventType::PassiveTriggered)==0&&cancelled.find("F")->vigil_charges==(border==StatusBorder::Golden?5u:0u),"dead aggressor charge border");}
 Fixture reflected;InitialRuntime mirror{"B",200,{{EffectKind::Reflect,2,TickPolicy::NaturalOnly,0,100}},{{"multi",0}}};Battle death(reflected.roster,reflected.rules,{{"F",50},{"P",1000},{"B",1000},{"B2",1000}},{mirror});r=death.apply({"B",ActionType::Attack,"F"});check(death.find("F")->health==0&&!shield(death,"P"),"Felipe dead after counter: no shield");
 Fixture tied;Battle tie(tied.roster,tied.rules,{{"F",500},{"P",490},{"B",1000},{"B2",1000}});r=tie.apply({"B",ActionType::Attack,"F"});check(shield(tie,"F")&&!shield(tie,"P"),"equal HP percent prefers Felipe");
 Fixture suppressed;InitialRuntime suppress{"F",100,{{EffectKind::Suppression,2,TickPolicy::NaturalOnly,0}},{{"F-A1",0}}};Battle muted(suppressed.roster,suppressed.rules,{}, {suppress});r=muted.apply({"B",ActionType::Attack,"F"});check(count(r,EventType::PassiveTriggered)==0&&muted.find("F")->vigil_charges==4,"suppression disables native passive, preserves golden charge");
 Fixture lethal;lethal.roster[2].attack=2000;Battle over(lethal.roster,lethal.rules);r=over.apply({"B",ActionType::Attack,"P"});check(over.find("P")->health==0&&count(r,EventType::PassiveTriggered)==1,"lethal ally hit counts if Felipe survives");
 Fixture slots;Definition q{"Q",Team::A,2000,1,60};q.stats.block=0;q.formation_slot=1;slots.roster[1].formation_slot=2;slots.roster[0].formation_slot=3;slots.roster.push_back(q);Battle slotTie(slots.roster,slots.rules,{{"F",1000},{"P",500},{"B",1000},{"B2",1000},{"Q",1000}});r=slotTie.apply({"B",ActionType::Attack,"F"});check(shield(slotTie,"Q")&&!shield(slotTie,"P"),"equal allies use formation slot, not lexical ID");
 Fixture queued;queued.roster[2].max_health=15;InitialRuntime oldCounter{"F",100,{{EffectKind::Counter,2,TickPolicy::NaturalOnly,0}},{{"F-A1",0}}};Battle queueDeath(queued.roster,queued.rules,{}, {oldCounter});r=queueDeath.apply({"B",ActionType::Attack,"F"});check(queueDeath.find("B")->health==0&&queueDeath.find("F")->vigil_charges==5&&count(r,EventType::PassiveTriggered)==0,"golden preserved if earlier reaction kills aggressor");
 Fixture six;six.roster[0].vigil->max_party_size=6;six.roster[0].vigil->initial_charges=4;Battle capacity(six.roster,six.rules);r=capacity.apply({"B",ActionType::Attack,"F"});check(capacity.find("F")->vigil_charges==5&&count(r,EventType::PassiveTriggered)==0,"capacity six independent of selected roster");
 std::cout<<"REG_FELIPE_TESTS_RESULT passed=13 total=13\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
